func:
// Parâmetros das regras de negócio (docs/regras-de-negocio.md).
// Para testes, é possível sobrescrever valores com a variável de ambiente
// SMARTFARM_PARAMETROS, em JSON. Ex.: {"tempoMaxIrrigacaoMin": 1}
const padrao = {
    umidadeMin: 30,             // % - abaixo disso, irrigar (R1)
    umidadeAlvo: 60,            // % - ao atingir, desligar (R1)
    nivelCritico: 20,           // % - abaixo disso, bloquear a bomba (R3)
    nivelLibera: 25,            // % - acima disso, liberar o bloqueio (R3)
    chuvaLimite: 60,            // % - probabilidade que adia a irrigação (R2)
    tempoMaxIrrigacaoMin: 15,   // min - tempo máximo com a bomba ligada (R4)
    pausaAposTempoMaxMin: 60,   // min - pausa da irrigação automática após R4
    semTelemetriaS: 60,         // s - sem telemetria por mais que isso = falha (R5)
    difTempMaxC: 5,             // °C - diferença sensor x API considerada suspeita (R6)
    difTempMinutos: 30,         // min - tempo de diferença até alertar (R6)
    intervaloAlertaMin: 30,     // min - intervalo mínimo entre alertas do mesmo tipo
    vazaoLpm: 2,                // L/min - vazão nominal da bomba (R7)
    reservatorioL: 200,         // L - capacidade do reservatório
    rotinaFixaLDia: 60          // L/dia - consumo de uma rotina fixa (2 x 15 min)
};
let extra = {};
const textoExtra = env.get("SMARTFARM_PARAMETROS");
if (textoExtra) {
    try { extra = JSON.parse(textoExtra); }
    catch (e) { node.warn("SMARTFARM_PARAMETROS inválido, usando os valores padrão."); }
}
global.set("params", Object.assign({}, padrao, extra));

if (!global.get("inicioSistema")) global.set("inicioSistema", Date.now());
global.set("fluxoIniciadoEm", Date.now());
if (!global.get("irrigacoes")) global.set("irrigacoes", []);
if (!global.get("adiamentos")) global.set("adiamentos", []);

// Estado da bomba: o valor real vem do Dispositivo B (mensagem retida de status).
const b = global.get("bomba") || {};
global.set("bomba", { estado: b.estado || 0, inicioTs: b.inicioTs || null, bloqueio: null,
                      reservatorioBloqueado: false, pausaAte: b.pausaAte || null });
node.status({ fill: "green", shape: "dot", text: "parâmetros carregados" });
return null;

// Valida a telemetria do Dispositivo A, guarda os valores mais recentes
// e dispara a gravação no InfluxDB e a avaliação das regras.
const d = msg.payload;
const campos = ["umidade_solo", "temperatura", "umidade_ar", "nivel"];
if (typeof d !== "object" || d === null || campos.some(k => typeof d[k] !== "number" || isNaN(d[k]))) {
    node.warn("Telemetria inválida ignorada: " + JSON.stringify(d));
    return null;
}
const t = { ts: Date.now() };
campos.forEach(k => t[k] = d[k]);
global.set("telemetria", t);
node.status({ fill: "green", shape: "dot", text: `solo ${t.umidade_solo}% · nível ${t.nivel}%` });

const gravar = {
    measurement: "telemetria",
    payload: [
        { umidade_solo: t.umidade_solo, temperatura: t.temperatura, umidade_ar: t.umidade_ar, nivel: t.nivel },
        { dispositivo: "dispA" }
    ]
};
return [gravar, { topic: "telemetria" }];

// Regras R1 a R5. Executa a cada telemetria, a cada 10 s e a cada nova previsão do tempo.
// Prioridade: falha de comunicação (R5) > reservatório (R3) > tempo máximo (R4) > chuva (R2) > demanda (R1).
const p = global.get("params");
if (!p) return null;
const t = global.get("telemetria");
const c = global.get("clima") || {};
const b = global.get("bomba") || { estado: 0 };
const agora = Date.now();
const alertas = [];
let desejado = null;   // "ligar", "desligar" ou null (manter como está)
let motivo = null;
let bloqueio = null;

const semTelemetria = !t || (agora - t.ts) > p.semTelemetriaS * 1000;
// Logo após iniciar o Node-RED, espera a primeira telemetria antes de acusar falha.
if (semTelemetria && agora - (global.get("fluxoIniciadoEm") || 0) < p.semTelemetriaS * 1000) {
    node.status({ fill: "grey", shape: "ring", text: "aguardando telemetria" });
    return null;
}

if (semTelemetria) {
    // R5 - falha de comunicação: desliga por segurança
    desejado = "desligar"; motivo = "falha"; bloqueio = "falha";
    if (!b.alertaSemTelemetria) {
        alertas.push({ tipo: "sem_telemetria",
            mensagem: `⚠️ Sem telemetria do Dispositivo A há mais de ${p.semTelemetriaS} s. A bomba foi desligada por segurança.` });
        b.alertaSemTelemetria = true;
    }
} else {
    if (b.alertaSemTelemetria) {
        b.alertaSemTelemetria = false;
        alertas.push({ tipo: "telemetria_restabelecida", mensagem: "✅ Telemetria do Dispositivo A restabelecida." });
    }

    // R3 - proteção do reservatório, com histerese (bloqueia < 20%, libera > 25%)
    if (t.nivel < p.nivelCritico) b.reservatorioBloqueado = true;
    else if (t.nivel > p.nivelLibera) b.reservatorioBloqueado = false;

    const climaRecente = c.ts && (agora - c.ts) < 30 * 60 * 1000;
    const chuvaPrevista = climaRecente && c.prob_chuva >= p.chuvaLimite;
    const emPausa = b.pausaAte && agora < b.pausaAte;
    const tempoLigadaMin = (b.estado === 1 && b.inicioTs) ? (agora - b.inicioTs) / 60000 : 0;

    if (b.reservatorioBloqueado) {
        desejado = "desligar"; motivo = "reservatorio"; bloqueio = "reservatorio";
        if (!b.alertaReservatorio) {
            alertas.push({ tipo: "reservatorio_critico",
                mensagem: `🔴 Reservatório em nível crítico (${t.nivel}%). Bomba bloqueada até o nível passar de ${p.nivelLibera}%.` });
            b.alertaReservatorio = true;
        }
    } else if (tempoLigadaMin > p.tempoMaxIrrigacaoMin) {
        // R4 - tempo máximo: desliga e pausa a irrigação automática
        desejado = "desligar"; motivo = "tempo_maximo"; bloqueio = "tempo_maximo";
        b.pausaAte = agora + p.pausaAposTempoMaxMin * 60000;
        alertas.push({ tipo: "tempo_maximo",
            mensagem: `⏱️ A bomba ficou ligada ${p.tempoMaxIrrigacaoMin} min sem o solo chegar a ${p.umidadeAlvo}%. ` +
                      `Ela foi desligada e a irrigação automática ficará pausada por ${p.pausaAposTempoMaxMin} min. ` +
                      `Verifique o sensor de umidade e se há vazamento.` });
    } else if (emPausa) {
        desejado = "desligar"; motivo = "tempo_maximo"; bloqueio = "tempo_maximo";
    } else if (chuvaPrevista) {
        // R2 - chuva prevista: suspende a irrigação por demanda
        desejado = "desligar"; motivo = "chuva"; bloqueio = "chuva";
        if (!b.alertaChuva && t.umidade_solo < p.umidadeMin) {
            alertas.push({ tipo: "chuva_prevista",
                mensagem: `🌧️ Chuva prevista nas próximas 3 h (${c.prob_chuva}%). A irrigação foi adiada, ` +
                          `mesmo com o solo em ${t.umidade_solo}%.` });
            const adiamentos = (global.get("adiamentos") || []).filter(a => agora - a.ts < 7 * 86400000);
            adiamentos.push({ ts: agora });
            global.set("adiamentos", adiamentos);
            b.alertaChuva = true;
        }
    } else {
        // R1 - irrigação por demanda, com histerese (liga < 30%, desliga >= 60%)
        if (t.umidade_solo < p.umidadeMin) { desejado = "ligar"; motivo = "demanda"; }
        else if (t.umidade_solo >= p.umidadeAlvo) { desejado = "desligar"; motivo = "demanda"; }
    }

    if (!b.reservatorioBloqueado) b.alertaReservatorio = false;
    if (!chuvaPrevista) b.alertaChuva = false;
}
b.bloqueio = bloqueio;

// Publica o comando só quando o estado real é diferente do desejado.
// Se o Dispositivo B não confirmar, repete a cada 15 s.
let comando = null;
if (desejado) {
    const quer = desejado === "ligar" ? 1 : 0;
    const repetir = b.ultimoComando !== desejado || (agora - (b.ultimoComandoTs || 0)) > 15000;
    if (b.estado !== quer && repetir) {
        b.ultimoComando = desejado;
        b.ultimoComandoTs = agora;
        b.ultimoMotivo = motivo;
        comando = { payload: JSON.stringify({ acao: desejado }) };
    }
}
global.set("bomba", b);

const texto = bloqueio ? `bloqueada (${bloqueio})` : (b.estado === 1 ? "bomba ligada" : "bomba desligada");
node.status({ fill: bloqueio ? "yellow" : (b.estado === 1 ? "blue" : "grey"), shape: "dot", text: texto });

return [comando, alertas.map(a => ({ payload: a }))];

// R6 - validação do sensor: compara a temperatura do DHT22 com a do OpenWeather.
const p = global.get("params");
const t = global.get("telemetria");
const c = global.get("clima") || {};
const agora = Date.now();
const s = global.get("r6") || {};
if (!p || !t || typeof c.temperatura !== "number" || !c.tsTemperatura || agora - c.tsTemperatura > 30 * 60000) return null;

const diferenca = Math.abs(t.temperatura - c.temperatura);
let alerta = null;
if (diferenca > p.difTempMaxC) {
    if (!s.desde) s.desde = agora;
    if (!s.alertado && agora - s.desde >= p.difTempMinutos * 60000) {
        s.alertado = true;
        alerta = { payload: { tipo: "sensor_divergente",
            mensagem: `🌡️ Possível falha no sensor: o DHT22 marca ${t.temperatura} °C e o OpenWeather ` +
                      `${c.temperatura} °C há mais de ${p.difTempMinutos} min.` } };
    }
} else {
    s.desde = null;
    s.alertado = false;
}
global.set("r6", s);
return alerta;

// R7 - registro de consumo. Recebe o estado real da bomba publicado pelo Dispositivo B.
const p = global.get("params");
const b = global.get("bomba") || { estado: 0 };
const novo = Number(msg.payload && msg.payload.bomba) === 1 ? 1 : 0;
const anterior = b.estado;
const agora = Date.now();
const gravar = [];

if (novo === 1 && anterior !== 1) b.inicioTs = agora;

if (novo === 0 && anterior === 1 && b.inicioTs) {
    const duracao_s = Math.round((agora - b.inicioTs) / 1000);
    const litros = Math.round(duracao_s / 60 * p.vazaoLpm * 100) / 100;
    const irrigacoes = (global.get("irrigacoes") || []).filter(i => agora - i.ts < 7 * 86400000);
    irrigacoes.push({ ts: agora, duracao_s, litros });
    global.set("irrigacoes", irrigacoes);
    gravar.push({ measurement: "irrigacao", payload: [{ duracao_s, litros }, { dispositivo: "dispB" }] });
    b.inicioTs = null;
}

if (novo !== anterior) {
    gravar.push({ measurement: "bomba",
                  payload: [{ estado: novo }, { dispositivo: "dispB", motivo: b.ultimoMotivo || "desconhecido" }] });
}
b.estado = novo;
global.set("bomba", b);
node.status({ fill: novo ? "blue" : "grey", shape: "dot", text: novo ? "ligada" : "desligada" });
return [gravar];

// Monta as duas consultas ao OpenWeather: clima atual e previsão das próximas 3 h.
// Variáveis de ambiente: OPENWEATHER_API_KEY (obrigatória) e OPENWEATHER_CIDADE (padrão: Sao Paulo,BR).
const chave = env.get("OPENWEATHER_API_KEY");
if (!chave) {
    node.warn("Defina a variável de ambiente OPENWEATHER_API_KEY.");
    node.status({ fill: "red", shape: "ring", text: "sem chave da API" });
    return null;
}
const base = env.get("OPENWEATHER_API_BASE") || "https://api.openweathermap.org";
const cidade = encodeURIComponent(env.get("OPENWEATHER_CIDADE") || "Sao Paulo,BR");
node.status({ fill: "green", shape: "dot", text: new Date().toLocaleTimeString("pt-BR") });
return [
    { url: `${base}/data/2.5/weather?q=${cidade}&units=metric&appid=${chave}` },
    { url: `${base}/data/2.5/forecast?q=${cidade}&units=metric&cnt=1&appid=${chave}` }
];

// Guarda a temperatura atual informada pela API (extraída de main.temp pelo nó anterior).
if (typeof msg.payload !== "number") {
    node.warn("Resposta inesperada do OpenWeather (clima atual). Código HTTP: " + msg.statusCode);
    return null;
}
const c = global.get("clima") || {};
c.temperatura = msg.payload;
c.tsTemperatura = Date.now();
global.set("clima", c);
node.status({ fill: "green", shape: "dot", text: `${msg.payload} °C` });
return null;

// Probabilidade de chuva no próximo bloco de 3 h da previsão (campo "pop", de 0 a 1).
const r = msg.payload;
if (!r || !Array.isArray(r.list) || r.list.length === 0) {
    node.warn("Resposta inesperada do OpenWeather (previsão). Código HTTP: " + msg.statusCode);
    return null;
}
const prob = Math.round((r.list[0].pop || 0) * 100);
const c = global.get("clima") || {};
c.prob_chuva = prob;
c.ts = Date.now();
global.set("clima", c);
node.status({ fill: "green", shape: "dot", text: `chuva em 3 h: ${prob}%` });

const campos = { prob_chuva: prob };
if (typeof c.temperatura === "number") campos.temperatura = c.temperatura;
return [{ measurement: "clima", payload: [campos, { fonte: "openweather" }] }, { topic: "clima" }];

// Intervalo mínimo entre alertas do mesmo tipo, para não lotar o Telegram.
const p = global.get("params") || { intervaloAlertaMin: 30 };
const a = msg.payload;
const agora = Date.now();
const ultimos = global.get("ultimosAlertas") || {};
if (ultimos[a.tipo] && agora - ultimos[a.tipo] < p.intervaloAlertaMin * 60000) return null;
ultimos[a.tipo] = agora;
global.set("ultimosAlertas", ultimos);
return msg;

// Monta o envio do alerta pela Telegram Bot API (método sendMessage).
// Variáveis de ambiente: TELEGRAM_BOT_TOKEN e TELEGRAM_CHAT_ID (chat que recebe os alertas).
const token = env.get("TELEGRAM_BOT_TOKEN");
const chat = env.get("TELEGRAM_CHAT_ID");
const base = env.get("TELEGRAM_API_BASE") || "https://api.telegram.org";
msg.alerta = msg.payload;
if (!token || !chat) {
    node.warn("Telegram não configurado: alerta registrado sem envio. " + msg.alerta.mensagem);
    msg.payload = { ok: false };
    return [null, msg];
}
msg.method = "POST";
msg.url = `${base}/bot${token}/sendMessage`;
msg.headers = { "content-type": "application/json" };
msg.payload = { chat_id: chat, text: msg.alerta.mensagem };
return [msg, null];

// Busca mensagens novas enviadas ao bot (getUpdates), sem precisar de HTTPS nem porta aberta.
const token = env.get("TELEGRAM_BOT_TOKEN");
if (!token) return null;
const base = env.get("TELEGRAM_API_BASE") || "https://api.telegram.org";
const agora = Date.now();
const ocupado = global.get("tgOcupadoDesde");
if (ocupado && agora - ocupado < 30000) return null;   // consulta anterior ainda em andamento
global.set("tgOcupadoDesde", agora);
const offset = global.get("tgOffset") || 0;
msg.method = "GET";
msg.url = `${base}/bot${token}/getUpdates?timeout=0&offset=${offset}`;
return msg;

// Responde aos comandos do menu de consulta (docs/bot-telegram.md).
// Só chats listados em TELEGRAM_CHAT_IDS_AUTORIZADOS (ou TELEGRAM_CHAT_ID) recebem resposta.
global.set("tgOcupadoDesde", null);
const r = msg.payload;
if (!r || r.ok !== true || !Array.isArray(r.result)) {
    node.warn("Falha ao buscar mensagens do bot. Código HTTP: " + msg.statusCode);
    return null;
}
const token = env.get("TELEGRAM_BOT_TOKEN");
const base = env.get("TELEGRAM_API_BASE") || "https://api.telegram.org";
const autorizados = (env.get("TELEGRAM_CHAT_IDS_AUTORIZADOS") || env.get("TELEGRAM_CHAT_ID") || "")
    .split(",").map(s => s.trim()).filter(Boolean);

const p = global.get("params") || {};
const t = global.get("telemetria") || {};
const b = global.get("bomba") || {};
const c = global.get("clima") || {};
const agora = Date.now();

const fmt = (v, casas = 0) => (typeof v !== "number" || isNaN(v)) ? "–" : v.toFixed(casas).replace(".", ",");
const idadeS = t.ts ? Math.round((agora - t.ts) / 1000) : null;
const desatualizado = idadeS === null || idadeS > (p.semTelemetriaS || 60);

const dias = Math.min(7, Math.max(1, Math.ceil((agora - (global.get("inicioSistema") || agora)) / 86400000)));
const irrigacoes = (global.get("irrigacoes") || []).filter(i => agora - i.ts < 7 * 86400000);
const usadoL = irrigacoes.reduce((s, i) => s + i.litros, 0);
const rotinaL = (p.rotinaFixaLDia || 60) * dias;
const adiadas = (global.get("adiamentos") || []).filter(a => agora - a.ts < 7 * 86400000).length;
const consumoDia = usadoL / dias;
const autonomia = (typeof t.nivel === "number" && consumoDia > 0)
    ? fmt(t.nivel / 100 * (p.reservatorioL || 200) / consumoDia, 1) + " dias" : "sem consumo registrado";

function faixa(u) {
    if (typeof u !== "number") return "sem leitura";
    return u < (p.umidadeMin || 30) ? "seco" : (u < (p.umidadeAlvo || 60) ? "ideal" : "acima do ideal");
}
function textoBomba() {
    const motivos = { chuva: "chuva prevista", reservatorio: "reservatório crítico",
                      tempo_maximo: "tempo máximo atingido", falha: "sem telemetria" };
    if (b.bloqueio) return `bloqueada (${motivos[b.bloqueio] || b.bloqueio})`;
    return b.estado === 1 ? "ligada" : "desligada";
}
const aviso = desatualizado ? "\n⚠️ Sem leitura recente do Dispositivo A: os valores podem estar desatualizados." : "";

const respostas = {
    "/status": () =>
        `🌱 Umidade do solo: ${fmt(t.umidade_solo)}% (${faixa(t.umidade_solo)})\n` +
        `💧 Reservatório: ${fmt(t.nivel)}% · autonomia ≈ ${autonomia}\n` +
        `🌧️ Chuva prevista (3 h): ${fmt(c.prob_chuva)}%\n` +
        `⚙️ Bomba: ${textoBomba()}\n` +
        `Última leitura: ${idadeS === null ? "nenhuma" : "há " + idadeS + " s"}` + aviso,
    "/umidade": () => `🌱 Umidade do solo: ${fmt(t.umidade_solo)}% (${faixa(t.umidade_solo)}). ` +
                      `Faixa ideal: ${p.umidadeMin}% a ${p.umidadeAlvo}%.` + aviso,
    "/nivel": () => `💧 Reservatório: ${fmt(t.nivel)}% · autonomia ≈ ${autonomia}` +
                    (t.nivel < p.nivelCritico ? "\n🔴 Nível crítico: bomba bloqueada." : "") + aviso,
    "/chuva": () => `🌧️ Chuva prevista nas próximas 3 h: ${fmt(c.prob_chuva)}%. ` +
                    (c.prob_chuva >= p.chuvaLimite ? "Irrigação adiada." : "Irrigação liberada."),
    "/bomba": () => `⚙️ Bomba: ${textoBomba()}.` + aviso,
    "/economia": () => `📊 Últimos ${dias} dia(s): ${fmt(usadoL, 1)} L usados × ${fmt(rotinaL)} L de uma rotina fixa. ` +
                       `Economia de ${fmt((1 - usadoL / rotinaL) * 100)}%. ${adiadas} irrigação(ões) adiada(s) por chuva.`
};
const ajuda = "Comandos disponíveis:\n/status · /umidade · /nivel · /chuva · /bomba · /economia";
const teclado = { keyboard: [["/status"], ["/umidade", "/nivel"], ["/chuva", "/bomba"], ["/economia", "/ajuda"]],
                  resize_keyboard: true };

let offset = global.get("tgOffset") || 0;
const envios = [];
for (const u of r.result) {
    offset = Math.max(offset, u.update_id + 1);
    const m = u.message;
    if (!m || typeof m.text !== "string") continue;
    const chatId = String(m.chat.id);
    if (!autorizados.includes(chatId)) {
        node.warn("Mensagem de chat não autorizado ignorada.");
        continue;
    }
    const comando = m.text.trim().split(/[\s@]/)[0].toLowerCase();
    let texto;
    if (respostas[comando]) texto = respostas[comando]();
    else if (comando === "/start" || comando === "/ajuda") texto = ajuda;
    else texto = "Comando não reconhecido.\n" + ajuda;

    envios.push({
        method: "POST",
        url: `${base}/bot${token}/sendMessage`,
        headers: { "content-type": "application/json" },
        payload: { chat_id: m.chat.id, text: texto, reply_markup: teclado },
        comando: { comando: (respostas[comando] || comando === "/start" || comando === "/ajuda") ? comando : "desconhecido",
                   chat: "***" + chatId.slice(-3) }   // ID anonimizado para o banco de dados
    });
}
global.set("tgOffset", offset);
return [envios];

// Registra no InfluxDB o resultado de cada envio ao Telegram (alerta ou resposta do bot).
const ok = !!(msg.payload && msg.payload.ok);
if (!ok && msg.statusCode) {
    node.warn(`Telegram respondeu ${msg.statusCode}: ${JSON.stringify(msg.payload).slice(0, 200)}`);
}
if (msg.alerta) {
    return { measurement: "alertas", payload: [{ mensagem: msg.alerta.mensagem, enviado: ok ? 1 : 0 }, { tipo: msg.alerta.tipo }] };
}
if (msg.comando) {
    return { measurement: "comandos", payload: [{ chat: msg.comando.chat, respondido: ok ? 1 : 0 }, { comando: msg.comando.comando }] };
}
return null;
